<script setup lang="ts">import {computed} from 'vue';import {Endmember,SampleResult} from '../types/domain';import {percent} from '../utils/format';import DataTable from './common/DataTable.vue';const props=defineProps<{endmembers:Endmember[];sample:SampleResult}>();const lockedIndices=computed(()=>new Set(props.sample.locked_endmember_indices||props.sample.point_fit.locked_endmember_indices||[]));</script><template><DataTable :head="['端元','点估计配比','条件2.5%分位','条件97.5%分位']"><tr v-for="(e,i) in endmembers" :key="e.code"><td><span :class="['pigment','color-'+i]"/>{{e.name}}<span v-if="lockedIndices.has(i)" class="lock-tag">已锁定</span></td><td>{{percent(sample.point_fit.weights[i])}}</td><td>{{percent(sample.lower[i])}}</td><td>{{percent(sample.upper[i])}}</td></tr></DataTable></template>
